class Solution:
    def hardestWorker(self, n: int, logs: list[list[int]]) -> int:
        best_id = logs[0][0]
        max_dur = logs[0][1]
        prev_time = logs[0][1]

        for emp_id, leave_time in logs[1:]:
            dur = leave_time - prev_time
            if dur > max_dur or (dur == max_dur and emp_id < best_id):
                max_dur = dur
                best_id = emp_id
            prev_time = leave_time
        return best_id

class Solution {
public:
    int hardestWorker(int n, std::vector<std::vector<int>>& logs) {
        int best_id = logs[0][0];
        int max_dur = logs[0][1];
        int prev_time = logs[0][1];
        for (int i = 1; i < (int)logs.size(); i++) {
            int emp_id = logs[i][0];
            int leave_time = logs[i][1];
            int dur = leave_time - prev_time;
            if (dur > max_dur || (dur == max_dur && emp_id < best_id)) {
                max_dur = dur;
                best_id = emp_id;
            }
            prev_time = leave_time;
        }
        return best_id;
    }
};

class Solution {
    public int hardestWorker(int n, int[][] logs) {
        int bestId = logs[0][0];
        int maxDur = logs[0][1];
        int prevTime = logs[0][1];
        for (int i = 1; i < logs.length; i++) {
            int empId = logs[i][0];
            int leaveTime = logs[i][1];
            int dur = leaveTime - prevTime;
            if (dur > maxDur || (dur == maxDur && empId < bestId)) {
                maxDur = dur;
                bestId = empId;
            }
            prevTime = leaveTime;
        }
        return bestId;
    }
}

